/**
 * Split Web Requests
 * Turns the queue written by the request form (request.html) into one item per request,
 * shaped like a Gmail message so Prepare Email handles both sources the same way.
 *
 * Input:  /webRequests from Firebase ({ <key>: { name, email, subject, message, createdAt } }, null if empty).
 * Output: one item per request with `webRequestId`, `from`, `subject` and `text`.
 */

/** Maximum length of name and address (the form limits them as well). */
const MAX_FIELD = 200;
const queue = $input.first().json || {};

return Object.entries(queue)
  .filter(([, request]) => request && typeof request === 'object' && request.email)
  .map(([webRequestId, request]) => ({
    json: {
      webRequestId,
      from: {
        value: [
          {
            address: String(request.email).trim().slice(0, MAX_FIELD),
            name: String(request.name || '').trim().slice(0, MAX_FIELD),
          },
        ],
      },
      subject: String(request.subject || ''),
      text: String(request.message || ''),
    },
  }));

/**
 * Prepare Email
 * Normalizes every incoming Gmail message so the rest of the workflow sees one shape.
 *
 * Input:  raw messages from the Gmail Trigger (simple: false), or web form requests from Split Web Requests
 *         (same shape plus `webRequestId`).
 * Output: one item per mail, shaped as {@link PreparedMail}.
 *
 * @typedef {Object} PreparedMail
 * @property {string|null} messageId     Gmail message id, used later for reply and labels (null for web requests).
 * @property {string|null} webRequestId  Firebase key of a web form request (null for mails).
 * @property {string} from       Sender address.
 * @property {string} fromName   Sender display name (may be empty).
 * @property {string} subject    Trimmed subject line.
 * @property {string} body       Plain-text body, cut to MAX_BODY characters.
 * @property {string} dateKey    Today as yyyy-MM-dd (Europe/Berlin), key of the daily request counter.
 */

/** Maximum number of body characters sent to the AI (keeps token costs bounded). */
const MAX_BODY = 8000;
const today = DateTime.now().setZone('Europe/Berlin');

return $input.all().map((item) => {
  const mail = item.json;

  return {
    json: {
      messageId: mail.id || null,
      webRequestId: mail.webRequestId || null,
      from: mail.from?.value?.[0]?.address || mail.from?.text || '',
      fromName: mail.from?.value?.[0]?.name || '',
      subject: String(mail.subject || '').trim(),
      body: String(mail.text || mail.snippet || '').trim().slice(0, MAX_BODY),
      dateKey: today.toFormat('yyyy-MM-dd'),
    },
  };
});

/**
 * Check Limit
 * Flags every mail as within or over today's quota, in arrival order (cost airbag).
 *
 * Input:  today's counter value from Firebase (Get Request Counter, null if no request yet).
 * Output: the mails from Prepare Email, each extended with `withinLimit: boolean`.
 */

/** Maximum number of AI-generated tickets per day. */
const DAILY_LIMIT = 10;
const used = Number($input.first().json.data) || 0;
const mails = $('Prepare Email').all();

return mails.map((mail, i) => ({
  json: { ...mail.json, withinLimit: used + i < DAILY_LIMIT },
  pairedItem: { item: 0 },
}));

/**
 * Build Task
 * Validates the AI output and maps it to the Join task shape stored in Firebase.
 * Falls back to the raw mail for missing fields, so no request gets lost.
 *
 * Input:  Extract Task results ({ output: { title, description, category, priority, dueDate, subtasks } }).
 * Output: one Join task per mail, created in the "triage" column with the sender as external creator.
 */

const CATEGORIES = ['User Story', 'Technical task', 'Bug'];
const PRIORITIES = ['urgent', 'medium', 'low'];
const AI_NOTE = 'This ticket was AI-generated.';
const today = DateTime.now().setZone('Europe/Berlin');

/**
 * Converts a value to a trimmed string and cuts it to a maximum length.
 * @param {*} value Any value, null/undefined become an empty string.
 * @param {number} max Maximum number of characters.
 * @returns {string}
 */
function text(value, max) {
  return String(value ?? '').trim().slice(0, max);
}

/**
 * Returns a valid due date: the AI date if it is a real, non-past date, otherwise today + 7 days.
 * @param {string} value Date from the AI in YYYY-MM-DD format (empty if the mail names none).
 * @returns {string} ISO date (YYYY-MM-DD).
 */
function dueDate(value) {
  const d = DateTime.fromISO(String(value ?? ''), { zone: 'Europe/Berlin' });
  if (/^\d{4}-\d{2}-\d{2}$/.test(value) && d.isValid && d >= today.startOf('day')) return d.toISODate();
  return today.plus({ days: 7 }).toISODate();
}

return $input.all().map((item, i) => {
  const mail = $('Check Limit').itemMatching(i).json;
  const ai = item.json.output ?? {};
  const subtasks = Array.isArray(ai.subtasks) ? ai.subtasks : [];
  const description = text(ai.description, 600) || text(mail.body, 600);

  return {
    json: {
      column: 'triage',
      title: text(ai.title, 80) || text(mail.subject, 80) || 'Request via email',
      description: description ? `${description}\n\n${AI_NOTE}` : AI_NOTE,
      dueDate: dueDate(ai.dueDate),
      category: CATEGORIES.includes(ai.category) ? ai.category : 'User Story',
      priority: PRIORITIES.includes(ai.priority) ? ai.priority : 'medium',
      assignedContacts: [],
      subtasks: subtasks.slice(0, 5).map((s) => text(s, 80)).filter(Boolean).map((name) => ({ name, checked: false })),
      createdAt: new Date().toISOString(),
      source: 'email',
      requester: text(mail.from, 200),
      requesterName: text(mail.fromName, 200),
      dateKey: mail.dateKey,
    },
    pairedItem: { item: i },
  };
});

/**
 * Compose Reply
 * Builds the answer for every outcome in one place: ticket created, daily limit reached or error.
 * The outcome follows from the node the items come from.
 *
 * Input:  items from Increment Request Counter (created), the false branch of Within Limit? (limit)
 *         or Log Error (error).
 * Output: one item per request with recipient, subject, text and the Gmail label to file it under.
 */

const LABEL_DONE = 'Label_6104079102047073068'; // "erledigt"
const LABEL_MANUAL_REVIEW = 'Label_4915219999416167153'; // "zu bearbeiten"
const OUTCOMES = { 'Increment Request Counter': 'created', 'Within Limit?': 'limit' };
const outcome = OUTCOMES[$prevNode.name] ?? 'error';

/** Answer text per outcome (between greeting and signature). */
const TEXTS = {
  created: (task) => [
    'thank you for your request. A ticket has been created on our Join board:',
    '',
    `"${task.title}"`,
    `Category: ${task.category} · Priority: ${task.priority} · Due: ${task.dueDate}`,
    '',
    'Our team will review it in triage. You will get an email whenever its status changes.',
  ].join('\n'),
  limit: () => [
    'thank you for your request. The daily limit of AI-generated requests has been reached, so no ticket was created automatically.',
    '',
    'Your request has not been lost: our team will review it manually. You can also send new requests again tomorrow.',
  ].join('\n'),
  error: () => 'thank you for your request. We have received it and our team will get back to you shortly.',
};

return $input.all().map((item, i) => {
  const mail = $('Check Limit').itemMatching(i).json;
  const task = outcome === 'created' ? $('Build Task').itemMatching(i).json : null;
  const greeting = `Hello${mail.fromName ? ' ' + mail.fromName : ''},`;
  // Web requests get a new mail instead of a reply, so it quotes the request
  // (the team also reviews it from there under "zu bearbeiten").
  const quote = mail.webRequestId ? `\n\n--- Your request ---\nSubject: ${mail.subject}\n\n${mail.body}` : '';

  return {
    json: {
      messageId: mail.messageId,
      webRequestId: mail.webRequestId,
      to: mail.from,
      subject: task ? `Your request: ${task.title}` : 'Your request has been received',
      message: `${greeting}\n\n${TEXTS[outcome](task)}\n\nBest regards\nThe Join team${quote}`,
      labelId: outcome === 'created' ? LABEL_DONE : LABEL_MANUAL_REVIEW,
    },
    pairedItem: { item: i },
  };
});
